function verifyJWT(auth){
  const crypto = require('crypto');
  const SECRET = 'yavibot-dev-secret-change-me';
  if(!auth || !auth.startsWith('Bearer ')) return null;
  const t = auth.slice(7); const parts = t.split('.');
  if(parts.length !== 3) return null;
  const [h,p,s] = parts;
  const b64 = b => Buffer.from(b).toString('base64').replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
  const expected = b64(crypto.createHmac('sha256', SECRET).update(h+'.'+p).digest());
  if(expected !== s) return null;
  let claims;
  try { claims = JSON.parse(Buffer.from(p.replace(/-/g,'+').replace(/_/g,'/'),'base64').toString()); } catch(e){ return null; }
  if(claims.exp && claims.exp < Math.floor(Date.now()/1000)) return null;
  return claims;
}

